"""Verify that Home category hooks are the only changes to existing NLP sources."""
import argparse
import json
import subprocess
from pathlib import Path

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--baseline', default='de79668f691cace89d690e69aed9b408ce9ae918')
args = parser.parse_args()
# Approved insertion sites, with their original context. Reversing only these
# hooks must recover the complete pre-feature source byte for byte.
PATCHES = json.loads(r'''[{"path": "lib/services/local_nlp_service.dart", "replacements": [{"before": "    String input,\n    List<String> activeCategories, {\n    Iterable<SmartEntryAccount> accounts = const [],\n  }) {\n    final rawInput = PakistaniLanguageNormalizer().normalize(input).normalized;\n    String lowerInput = rawInput.toLowerCase().replaceAll(\n", "after": "    String input,\n    List<String> activeCategories, {\n    Iterable<SmartEntryAccount> accounts = const [],\n    String? explicitExpenseCategory,\n  }) {\n    final rawInput = PakistaniLanguageNormalizer().normalize(input).normalized;\n    String lowerInput = rawInput.toLowerCase().replaceAll(\n"}, {"before": "      matchedCategoryTokens.addAll(candidate.split(' '));\n    }\n\n    for (final candidate in candidates) {\n      final mappedCategory = _normalizedLexicon[_normalize(candidate)];\n      if (mappedCategory != null &&\n          lowerActiveCategories.contains(mappedCategory.toLowerCase())) {\n", "after": "      matchedCategoryTokens.addAll(candidate.split(' '));\n    }\n\n    if (intent == SmartEntryIntent.addExpense &&\n        explicitExpenseCategory != null &&\n        activeCategories.contains(explicitExpenseCategory)) {\n      category = explicitExpenseCategory;\n      categoryFound = true;\n    }\n\n    for (final candidate in categoryFound ? const <String>[] : candidates) {\n      final mappedCategory = _normalizedLexicon[_normalize(candidate)];\n      if (mappedCategory != null &&\n          lowerActiveCategories.contains(mappedCategory.toLowerCase())) {\n"}]}, {"path": "lib/services/smart_input_engine.dart", "replacements": [{"before": "import 'voice_diagnostic_observer.dart';\nimport 'pakistani_language_normalizer.dart';\nimport 'smart_command.dart';\n\nclass SmartInputPlan {\n  final String originalText;\n  final PakistaniNormalizationResult normalization;\n  final SmartCommand command;\n\n  const SmartInputPlan({\n    required this.originalText,\n    required this.normalization,\n    required this.command,\n  });\n\n  String get normalizedText => normalization.normalized;\n  ParsedSmartEntryCommand get parsed => command.parsed;\n\n  bool get requiresAsrReview =>\n", "after": "import 'voice_diagnostic_observer.dart';\nimport 'pakistani_language_normalizer.dart';\nimport 'smart_command.dart';\nimport 'explicit_expense_category.dart';\n\nclass SmartInputPlan {\n  final String originalText;\n  final PakistaniNormalizationResult normalization;\n  final SmartCommand command;\n  final ExplicitExpenseCategory? expenseCategory;\n\n  const SmartInputPlan({\n    required this.originalText,\n    required this.normalization,\n    required this.command,\n    this.expenseCategory,\n  });\n\n  String get normalizedText => expenseCategory?.cleanedText ?? normalization.normalized;\n  ParsedSmartEntryCommand get parsed => command.parsed;\n\n  bool get requiresAsrReview =>\n"}, {"before": "    List<String> activeCategories, {\n    SmartInputSource source = SmartInputSource.typed,\n    Iterable<SmartEntryAccount> accounts = const [],\n  }) {\n    final normalization = normalizer.normalize(\n      input,\n      enableContextualAsrRepairs: source == SmartInputSource.voice,\n    );\n    final parsed = nlp.parseCommand(\n      normalization.normalized,\n      activeCategories,\n      accounts: accounts,\n    );\n    final command = _toTypedCommand(parsed, source);\n    if (VoiceDiagnosticObserver.active) {\n", "after": "    List<String> activeCategories, {\n    SmartInputSource source = SmartInputSource.typed,\n    Iterable<SmartEntryAccount> accounts = const [],\n    ExplicitExpenseCategory? expenseCategory,\n  }) {\n    final normalization = normalizer.normalize(\n      input,\n      enableContextualAsrRepairs: source == SmartInputSource.voice,\n    );\n    final parsed = nlp.parseCommand(\n      expenseCategory?.cleanedText ?? normalization.normalized,\n      activeCategories,\n      accounts: accounts,\n      explicitExpenseCategory: expenseCategory?.category,\n    );\n    final command = _toTypedCommand(parsed, source);\n    if (VoiceDiagnosticObserver.active) {\n"}, {"before": "      'query_metric': parsed.queryMetric?.name, 'time_range': parsed.timeRange.name,\n      'navigation_target': parsed.navigationTarget, 'app_action': parsed.appAction?.name,\n      'entry_type_filter': parsed.entryTypeFilter, 'has_explicit_date': parsed.hasExplicitDate,\n      'confidence_by_field': parsed.confidenceByField, 'clarification_reasons': parsed.clarificationReasons,\n      if (command is MutationCommand) 'selector': {'title': command.selector.title,\n        'amount': command.selector.amount, 'date': command.selector.date, 'type': command.selector.transactionType},\n", "after": "      'query_metric': parsed.queryMetric?.name, 'time_range': parsed.timeRange.name,\n      'navigation_target': parsed.navigationTarget, 'app_action': parsed.appAction?.name,\n      'entry_type_filter': parsed.entryTypeFilter, 'has_explicit_date': parsed.hasExplicitDate,\n      if (expenseCategory != null) 'explicit_category': {\n        'category': expenseCategory.category, 'issue': expenseCategory.issue,\n        'parsing_text': expenseCategory.cleanedText,\n      },\n      'confidence_by_field': parsed.confidenceByField, 'clarification_reasons': parsed.clarificationReasons,\n      if (command is MutationCommand) 'selector': {'title': command.selector.title,\n        'amount': command.selector.amount, 'date': command.selector.date, 'type': command.selector.transactionType},\n"}, {"before": "      originalText: input,\n      normalization: normalization,\n      command: command,\n    );\n  }\n\n", "after": "      originalText: input,\n      normalization: normalization,\n      command: command,\n      expenseCategory: expenseCategory,\n    );\n  }\n\n"}]}, {"path": "lib/features/smart_entry/smart_entry_controller.dart", "replacements": [{"before": "import '../../services/local_nlp_service.dart';\nimport '../../services/smart_command.dart';\nimport '../../services/smart_input_engine.dart';\n\n\n/// Feature-level entry point for Smart Entry interpretation.\n", "after": "import '../../services/local_nlp_service.dart';\nimport '../../services/smart_command.dart';\nimport '../../services/smart_input_engine.dart';\nimport '../../services/explicit_expense_category.dart';\nimport '../../services/primary_intent_router.dart';\nimport 'multi_entry_parser.dart';\n\n\n/// Feature-level entry point for Smart Entry interpretation.\n"}, {"before": "    List<String> categories, {\n    required SmartInputSource source,\n    Iterable<SmartEntryAccount> accounts = const [],\n  }) {\n    return _engine.parse(\n      input,\n      categories,\n      source: source,\n      accounts: accounts,\n    );\n  }\n}\n\nfinal smartEntryControllerProvider = Provider<SmartEntryController>(\n", "after": "    List<String> categories, {\n    required SmartInputSource source,\n    Iterable<SmartEntryAccount> accounts = const [],\n    ExplicitExpenseCategory? expenseCategory,\n    bool enableHomeExpenseCategories = false,\n  }) {\n    final category = expenseCategory ?? (enableHomeExpenseCategories\n        ? resolveHomeExpenseCategory(input, categories, source: source, accounts: accounts)\n        : null);\n    return _engine.parse(\n      input,\n      categories,\n      source: source,\n      accounts: accounts,\n      expenseCategory: category,\n    );\n  }\n\n  /// Opt-in only for Home single expenses; batch and other intent paths stay\n  /// on the original engine. Full-text routing/negation precedes subtraction.\n  ExplicitExpenseCategory? resolveHomeExpenseCategory(\n    String input,\n    List<String> categories, {\n    required SmartInputSource source,\n    Iterable<SmartEntryAccount> accounts = const [],\n  }) {\n    final text = _engine.normalizer.normalize(input,\n        enableContextualAsrRepairs: source == SmartInputSource.voice).normalized;\n    if (RegExp(r'\\b(nahi|nahin|mat|dont|don\\x27t|ya|or)\\b').hasMatch(text)) return null;\n    final route = const PrimaryIntentRouter().classify(text);\n    if (route.intent != RoutedSmartIntent.addExpense &&\n        route.intent != RoutedSmartIntent.editEntry &&\n        route.intent != RoutedSmartIntent.addIncome) return null;\n    const extractor = ExplicitExpenseCategoryExtractor();\n    final wallets = accounts.map((account) => account.name);\n    // Match saved names before normalization can remove punctuation from them.\n    final raw = extractor.extract(input, categories, walletNames: wallets) ??\n        extractor.extract(text, categories, walletNames: wallets);\n    final extracted = raw == null ? null : ExplicitExpenseCategory(\n      cleanedText: _engine.normalizer.normalize(raw.cleanedText,\n          enableContextualAsrRepairs: source == SmartInputSource.voice).normalized,\n      category: raw.category, issue: raw.issue,\n      hasAddInstruction: raw.hasAddInstruction,\n    );\n    if (extracted == null) return null;\n    if (route.intent == RoutedSmartIntent.editEntry ||\n        route.intent == RoutedSmartIntent.addIncome) {\n      if (!extracted.hasAddInstruction ||\n          RegExp(r'\\b(edit|change|update|modify|correct|badal|badlo|theek)\\b').hasMatch(text) ||\n          const PrimaryIntentRouter().classify(extracted.cleanedText).intent !=\n              RoutedSmartIntent.addExpense) return null;\n    }\n    if (const MultiEntryParser().tryParseBatch(extracted.cleanedText) != null ||\n        (extracted.needsClarification &&\n            const MultiEntryParser().tryParseBatch(text) != null)) return null;\n    return extracted;\n  }\n}\n\nfinal smartEntryControllerProvider = Provider<SmartEntryController>(\n"}]}, {"path": "lib/features/dashboard/dashboard_smart_entry_processing.dart", "replacements": [{"before": "    if (normalized.isEmpty) return false;\n\n    final categories = ref.read(categoryProvider);\n\n    if (source == SmartInputSource.typed || source == SmartInputSource.voice) {\n      final wallets = ref.read(walletProvider);\n", "after": "    if (normalized.isEmpty) return false;\n\n    final categories = ref.read(categoryProvider);\n    final expenseCategory = ref.read(smartEntryControllerProvider)\n        .resolveHomeExpenseCategory(normalized, categories,\n            source: source, accounts: _parsingAccounts());\n    if (expenseCategory?.needsClarification == true) {\n      _showTransactionInfo(expenseCategory!.issue!, title: 'Choose a category');\n      return false;\n    }\n\n    if (source == SmartInputSource.typed || source == SmartInputSource.voice) {\n      final wallets = ref.read(walletProvider);\n"}, {"before": "          .toList(growable: false);\n\n      final batchAttempt = ref.read(smartEntryBatchControllerProvider).tryBuild(\n            rawText: normalized,\n            categories: categories,\n            source: source,\n            accounts: accounts,\n", "after": "          .toList(growable: false);\n\n      final batchAttempt = ref.read(smartEntryBatchControllerProvider).tryBuild(\n            rawText: expenseCategory?.cleanedText ?? normalized,\n            categories: categories,\n            source: source,\n            accounts: accounts,\n"}, {"before": "      categories,\n      source: source,\n      accounts: _parsingAccounts(),\n    );\n    _debugSmartInputPlan(plan);\n    final command = plan.parsed;\n", "after": "      categories,\n      source: source,\n      accounts: _parsingAccounts(),\n      expenseCategory: expenseCategory,\n    );\n    _debugSmartInputPlan(plan);\n    final command = plan.parsed;\n"}, {"before": "    final result = command.toLegacyMap();\n    final learnedPreference = _learnedPreferenceFor(command.title);\n    if (result['type'] == 'expense' &&\n        result['category'] == 'General' &&\n        learnedPreference != null &&\n        categories.contains(learnedPreference.category)) {\n", "after": "    final result = command.toLegacyMap();\n    final learnedPreference = _learnedPreferenceFor(command.title);\n    if (result['type'] == 'expense' &&\n        plan.expenseCategory == null &&\n        result['category'] == 'General' &&\n        learnedPreference != null &&\n        categories.contains(learnedPreference.category)) {\n"}]}, {"path": "lib/features/dashboard/dashboard_voice.dart", "replacements": [{"before": "      final plan = ref.read(smartEntryControllerProvider).parse(\n        normalized, ref.read(categoryProvider),\n        source: SmartInputSource.voice, accounts: accounts,\n      );\n      final result = _voiceEntry.completeness.evaluate(plan, accounts: accounts);\n      _speechCachedCompleteness = result;\n      _speechCacheKey = key;\n      _speechTiming.mark('parse_completed');\n", "after": "      final plan = ref.read(smartEntryControllerProvider).parse(\n        normalized, ref.read(categoryProvider),\n        source: SmartInputSource.voice, accounts: accounts,\n        enableHomeExpenseCategories: true,\n      );\n      final result = plan.expenseCategory?.needsClarification == true\n          ? const SpeechCommandCompleteness.incomplete('category_instruction_incomplete')\n          : _voiceEntry.completeness.evaluate(plan, accounts: accounts);\n      _speechCachedCompleteness = result;\n      _speechCacheKey = key;\n      _speechTiming.mark('parse_completed');\n"}]}]''')
for patch in PATCHES:
    path = patch['path']
    current = Path(path).read_text()
    for replacement in reversed(patch['replacements']):
        assert current.count(replacement['after']) == 1, f'{path}: category hook changed'
        current = current.replace(replacement['after'], replacement['before'], 1)
    previous = subprocess.check_output(['git', 'show', f'{args.baseline}:{path}'], text=True)
    assert current == previous, f'{path}: unrelated NLP or execution logic changed'
print('Only approved Home expense category hooks changed; original parsing and execution logic preserved')
